public class InnerHyperParameterTuningJobTrainingJobDefinitionFactory(Action<Humidifier.SageMaker.HyperParameterTuningJobTypes.TrainingJobDefinition> factoryAction = null) : SubResourceFactory<Humidifier.SageMaker.HyperParameterTuningJobTypes.TrainingJobDefinition>
{

    internal InnerHyperParameterTuningJobAlgorithmSpecificationFactory AlgorithmSpecificationFactory { get; set; }

    internal InnerHyperParameterTuningJobOutputDataConfigFactory OutputDataConfigFactory { get; set; }

    internal InnerHyperParameterTuningJobVpcConfigFactory VpcConfigFactory { get; set; }

    internal InnerHyperParameterTuningJobCheckpointConfigFactory CheckpointConfigFactory { get; set; }

    internal InnerHyperParameterTuningJobStoppingConditionFactory StoppingConditionFactory { get; set; }

    internal InnerHyperParameterTuningJobResourceConfigFactory ResourceConfigFactory { get; set; }

    internal InnerHyperParameterTuningJobTuningObjectiveFactory TuningObjectiveFactory { get; set; }

    internal InnerHyperParameterTuningJobRetryStrategyFactory RetryStrategyFactory { get; set; }

    internal InnerHyperParameterTuningJobParameterRangesFactory HyperParameterRangesFactory { get; set; }

    protected override Humidifier.SageMaker.HyperParameterTuningJobTypes.TrainingJobDefinition Create()
    {
        var trainingJobDefinitionResult = CreateTrainingJobDefinition();
        factoryAction?.Invoke(trainingJobDefinitionResult);

        return trainingJobDefinitionResult;
    }

    private Humidifier.SageMaker.HyperParameterTuningJobTypes.TrainingJobDefinition CreateTrainingJobDefinition()
    {
        var trainingJobDefinitionResult = new Humidifier.SageMaker.HyperParameterTuningJobTypes.TrainingJobDefinition();

        return trainingJobDefinitionResult;
    }
    public override void CreateChildren(Humidifier.SageMaker.HyperParameterTuningJobTypes.TrainingJobDefinition result)
    {
        base.CreateChildren(result);

        result.AlgorithmSpecification ??= AlgorithmSpecificationFactory?.Build();
        result.OutputDataConfig ??= OutputDataConfigFactory?.Build();
        result.VpcConfig ??= VpcConfigFactory?.Build();
        result.CheckpointConfig ??= CheckpointConfigFactory?.Build();
        result.StoppingCondition ??= StoppingConditionFactory?.Build();
        result.ResourceConfig ??= ResourceConfigFactory?.Build();
        result.TuningObjective ??= TuningObjectiveFactory?.Build();
        result.RetryStrategy ??= RetryStrategyFactory?.Build();
        result.HyperParameterRanges ??= HyperParameterRangesFactory?.Build();
    }

} // End Of Class

